INSERT INTO research_tests (id, grp, name, symbol, period, trades, pf, t_stat, pos_years, verdict, notes, tested_on) VALUES
('S14-validation-s1', 'I', 'VALIDATION of S1: independent recompute from bars_1m SQL aggregates (no shared harness) + paper_engine MBO replay Mar–Apr 2025 of the fleet ids', 'NQ', '2010–2026 / 2025-03..04', 526, 1.60, 3.30, '14/16', 'edge', 'Independent recompute: n=526 avg $53.5 PF 1.60 t 3.30 14/16 (S1: 532 / 52.8 / 1.60 / 3.3). Engine vs research: prior-day hi/lo/close/IBS identical on every session; rsi2_20_day__vix20 9/9 days, anyweak_h1 13/13, wc_ibs30_h1 8/8, anyweak_h1__vix20 11/11; fills within a tick, P&L $4,978 vs $5,076 on common days. Two defects found: (1) build-hist/paper_engine predated the hold filters (ignored them, traded every day) — rebuilt, the 2,088 stale nq_bars rows for the hold ids redone (529); (2) the per-strategy consistency cap (100%, persists) froze anyweak/wc day variants after the 04-07 win — now 0 = off for the paper fleet, broker refusals logged.', '2026-10-11'),
('S11-nq-es-pairs', 'I', 'Intraday NQ/ES pairs reversion: 5-min log-ratio z-score (30/60/120 bars), enter |z|>2–2.5, exit at z=0 or 15:55, 1 MNQ vs 1.5 MES', 'NQ+ES', '2010–2026', 5919, 0.55, -14.1, '0/17', 'no edge', '−$10/pair at every setting (cost $8.57 RT); the spread does not revert intraday at a scale above costs.', '2026-10-11'),
('S12-fomc-day-intraday', 'I', 'FOMC decision days: 09:30→14:00, 14:00/14:05/14:30/15:00→15:55 long; 15:00→15:55 short', 'NQ', '2010–2026', 125, 1.48, 1.13, '9/17', 'weak', 'Longs negative in every window (15:00→15:55 −$27, PF 0.54); the short of the last hour +$17 PF 1.48 but h1 −$3 / h2 +$41, 8 trades/yr. Not a strategy.', '2026-10-11'),
('S13-gap-fade', 'I', 'Gap fade toward the prior 16:00 close (|gap| ≥ 0.3/0.5/0.8 ATR), exit at fill or 11:00 / 15:55', 'NQ', '2010–2026', 393, 1.35, 1.87, '9/17', 'weak', '≥0.8 ATR exit 11:00: +$17/MNQ PF 1.35, fills only 6%, years noisy (2020/2025/2026 carry it; 2019, 2021, 2023, 2024 negative), VIX non-monotonic. ≥0.3/0.5 ATR ≈ 0.', '2026-10-11')
